00058     public function reload($id = null, $type = null)
00059     {
00060         global $bearsamppRoot, $bearsamppConfig, $bearsamppLang;
00061         Log::reloadClass( $this );
00062 
00063         $this->name    = $bearsamppLang->getValue( Lang::MAILPIT );
00064         $this->version = $bearsamppConfig->getRaw( self::ROOT_CFG_VERSION );
00065         parent::reload( $id, $type );
00066 
00067         $this->enable  = $this->enable && $bearsamppConfig->getRaw( self::ROOT_CFG_ENABLE );
00068         $this->service = new Win32Service( self::SERVICE_NAME );
00069         $this->log     = Path::getLogsPath() . '/mailpit.log';
00070 
00071         if ( $this->bearsamppConfRaw !== false ) {
00072             $this->exe      = $this->symlinkPath . '/' . $this->bearsamppConfRaw[self::LOCAL_CFG_EXE];
00073             $this->webRoot  = $this->bearsamppConfRaw[self::LOCAL_CFG_WEB_ROOT];
00074             $this->uiPort   = intval( $this->bearsamppConfRaw[self::LOCAL_CFG_UI_PORT] );
00075             $this->smtpPort = intval( $this->bearsamppConfRaw[self::LOCAL_CFG_SMTP_PORT] );
00076             $this->listen   = $this->bearsamppConfRaw[self::LOCAL_CFG_LISTEN];
00077         }
00078 
00079         if ( !$this->enable ) {
00080             Log::info( $this->name . ' is not enabled!' );
00081 
00082             return;
00083         }
00084         if ( !is_dir( $this->currentPath ) ) {
00085             Log::error( sprintf( $bearsamppLang->getValue( Lang::ERROR_FILE_NOT_FOUND ), $this->name . ' ' . $this->version, $this->currentPath ) );
00086 
00087             return;
00088         }
00089         if ( !is_dir( $this->symlinkPath ) ) {
00090             Log::error( sprintf( $bearsamppLang->getValue( Lang::ERROR_FILE_NOT_FOUND ), $this->name . ' ' . $this->version, $this->symlinkPath ) );
00091 
00092             return;
00093         }
00094         if ( !is_file( $this->bearsamppConf ) ) {
00095             Log::error( sprintf( $bearsamppLang->getValue( Lang::ERROR_CONF_NOT_FOUND ), $this->name . ' ' . $this->version, $this->bearsamppConf ) );
00096 
00097             return;
00098         }
00099         if ( !is_file( $this->exe ) ) {
00100             Log::error( sprintf( $bearsamppLang->getValue( Lang::ERROR_EXE_NOT_FOUND ), $this->name . ' ' . $this->version, $this->exe ) );
00101 
00102             return;
00103         }
00104         if ( (empty( $this->webRoot ) && $this->webRoot !== '' || is_numeric( $this->webRoot )) ) {
00105             Log::error( sprintf( $bearsamppLang->getValue( Lang::ERROR_INVALID_PARAMETER ), self::LOCAL_CFG_WEB_ROOT, $this->webRoot ) );
00106 
00107             return;
00108         }
00109         if ( empty( $this->uiPort ) ) {
00110             Log::error( sprintf( $bearsamppLang->getValue( Lang::ERROR_INVALID_PARAMETER ), self::LOCAL_CFG_UI_PORT, $this->uiPort ) );
00111 
00112             return;
00113         }
00114         if ( empty( $this->smtpPort ) ) {
00115             Log::error( sprintf( $bearsamppLang->getValue( Lang::ERROR_INVALID_PARAMETER ), self::LOCAL_CFG_SMTP_PORT, $this->smtpPort ) );
00116 
00117             return;
00118         }
00119         if ( empty( $this->listen ) ) {
00120             Log::error( sprintf( $bearsamppLang->getValue( Lang::ERROR_INVALID_PARAMETER ), self::LOCAL_CFG_LISTEN, $this->listen ) );
00121 
00122             return;
00123         }
00124 
00125         $nssm = new Nssm( self::SERVICE_NAME );
00126         $nssm->setDisplayName( APP_TITLE . ' ' . $this->getName() );
00127         $nssm->setBinPath( $this->exe );
00128         $nssm->setParams( sprintf( self::SERVICE_PARAMS, $this->listen, $this->uiPort, $this->listen, $this->smtpPort, $this->webRoot ) );
00129         $nssm->setStart( Nssm::SERVICE_DEMAND_START );
00130         $nssm->setStdout( Path::getLogsPath() . '/mailpit.out.log' );
00131         $nssm->setStderr( Path::getLogsPath() . '/mailpit.err.log' );
00132 
00133         $this->service->setNssm( $nssm );
00134     }
