00141     protected function replaceAll($params)
00142     {
00143         $content = file_get_contents( $this->bearsamppConf );
00144 
00145         foreach ( $params as $key => $value ) {
00146             $content                      = preg_replace( '|' . $key . ' = .*|', $key . ' = ' . '"' . $value . '"', $content );
00147             $this->bearsamppConfRaw[$key] = $value;
00148             switch ( $key ) {
00149                 case self::LOCAL_CFG_UI_PORT:
00150                     $this->uiPort = intval( $value );
00151                     break;
00152                 case self::LOCAL_CFG_SMTP_PORT:
00153                     $this->smtpPort = intval( $value );
00154                     break;
00155             }
00156         }
00157 
00158         file_put_contents( $this->bearsamppConf, $content );
00159     }
