00166     public function rebuildConf()
00167     {
00168         global $bearsamppRegistry;
00169 
00170         Log::trace("Starting rebuildConf for Mailpit service");
00171         Log::trace("Checking if registry key exists for Mailpit service parameters");
00172 
00173         $registryPath = 'SYSTEM\CurrentControlSet\Services\\' . self::SERVICE_NAME . '\Parameters';
00174         Log::trace("Registry path: " . $registryPath);
00175 
00176         $exists = $bearsamppRegistry->exists(
00177             Registry::HKEY_LOCAL_MACHINE,
00178             $registryPath,
00179             Nssm::INFO_APP_PARAMETERS
00180         );
00181 
00182         if ( $exists ) {
00183             Log::trace("Registry key exists, updating service parameters");
00184 
00185             $serviceParams = sprintf(self::SERVICE_PARAMS, $this->listen, $this->uiPort, $this->listen, $this->smtpPort, $this->webRoot);
00186             Log::trace("Service parameters: " . $serviceParams);
00187 
00188             $result = $bearsamppRegistry->setExpandStringValue(
00189                 Registry::HKEY_LOCAL_MACHINE,
00190                 $registryPath,
00191                 Nssm::INFO_APP_PARAMETERS,
00192                 $serviceParams
00193             );
00194 
00195             Log::trace("Registry update " . ($result ? "succeeded" : "failed"));
00196             return $result;
00197         }
00198 
00199         Log::trace("Registry key does not exist for Mailpit service parameters");
00200         return false;
00201     }
