00212     public function changePort($port, $checkUsed = false, $wbProgressBar = null)
00213     {
00214         global $bearsamppWinbinder;
00215 
00216         if ( !Util::isValidPort( $port ) ) {
00217             Log::error( $this->getName() . ' port not valid: ' . $port );
00218 
00219             return false;
00220         }
00221 
00222         $port = intval( $port );
00223         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00224 
00225         $isPortInUse = Util::isPortInUse( $port );
00226         if ( !$checkUsed || $isPortInUse === false ) {
00227             // bearsampp.conf
00228             $this->setSmtpPort( $port );
00229             $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00230 
00231             // conf
00232             $this->update();
00233             $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00234 
00235             return true;
00236         }
00237 
00238         Log::debug( $this->getName() . ' port in used: ' . $port . ' - ' . $isPortInUse );
00239 
00240         return $isPortInUse;
00241     }
