00251     public function checkPort($port, $showWindow = false)
00252     {
00253         global $bearsamppLang, $bearsamppWinbinder;
00254         $boxTitle = sprintf( $bearsamppLang->getValue( Lang::CHECK_PORT_TITLE ), $this->getName(), $port );
00255 
00256         if ( !Util::isValidPort( $port ) ) {
00257             Log::error( $this->getName() . ' port not valid: ' . $port );
00258 
00259             return false;
00260         }
00261 
00262         $headers = HttpClient::getHeaders( $this->listen, $port );
00263         if ( !empty( $headers ) ) {
00264             if ( UtilString::contains( $headers[0], 'Mailpit' ) ) {
00265                 Log::debug( $this->getName() . ' port ' . $port . ' is used by: ' . str_replace( '220 ', '', $headers[0] ) );
00266                 if ( $showWindow ) {
00267                     $bearsamppWinbinder->messageBoxInfo(
00268                         sprintf( $bearsamppLang->getValue( Lang::PORT_USED_BY ), $port, str_replace( '220 ', '', $headers[0] ) ),
00269                         $boxTitle
00270                     );
00271                 }
00272 
00273                 return true;
00274             }
00275             Log::debug( $this->getName() . ' port ' . $port . ' is used by another application' );
00276             if ( $showWindow ) {
00277                 $bearsamppWinbinder->messageBoxWarning(
00278                     sprintf( $bearsamppLang->getValue( Lang::PORT_NOT_USED_BY ), $port ),
00279                     $boxTitle
00280                 );
00281             }
00282         }
00283         else {
00284             Log::debug( $this->getName() . ' port ' . $port . ' is not used' );
00285             if ( $showWindow ) {
00286                 $bearsamppWinbinder->messageBoxError(
00287                     sprintf( $bearsamppLang->getValue( Lang::PORT_NOT_USED ), $port ),
00288                     $boxTitle
00289                 );
00290             }
00291         }
00292 
00293         return false;
00294     }
