00320     protected function updateConfig($version = null, $sub = 0, $showWindow = false)
00321     {
00322         global $bearsamppLang, $bearsamppWinbinder;
00323 
00324         if ( !$this->enable ) {
00325             return true;
00326         }
00327 
00328         $version = $version == null ? $this->version : $version;
00329         Log::debug( ($sub > 0 ? str_repeat( ' ', 2 * $sub ) : '') . 'Update ' . $this->name . ' ' . $version . ' config' );
00330 
00331         $boxTitle = sprintf( $bearsamppLang->getValue( Lang::SWITCH_VERSION_TITLE ), $this->getName(), $version );
00332 
00333         $bearsamppConf = str_replace( 'mailpit' . $this->getVersion(), 'mailpit' . $version, $this->bearsamppConf );
00334         if ( !file_exists( $bearsamppConf ) ) {
00335             Log::error( 'bearsampp config files not found for ' . $this->getName() . ' ' . $version );
00336             if ( $showWindow ) {
00337                 $bearsamppWinbinder->messageBoxError(
00338                     sprintf( $bearsamppLang->getValue( Lang::BEARSAMPP_CONF_NOT_FOUND_ERROR ), $this->getName() . ' ' . $version ),
00339                     $boxTitle
00340                 );
00341             }
00342 
00343             return false;
00344         }
00345 
00346         $bearsamppConfRaw = parse_ini_file( $bearsamppConf );
00347         if ( $bearsamppConfRaw === false || !isset( $bearsamppConfRaw[self::ROOT_CFG_VERSION] ) || $bearsamppConfRaw[self::ROOT_CFG_VERSION] != $version ) {
00348             Log::error( 'bearsampp config file malformed for ' . $this->getName() . ' ' . $version );
00349             if ( $showWindow ) {
00350                 $bearsamppWinbinder->messageBoxError(
00351                     sprintf( $bearsamppLang->getValue( Lang::BEARSAMPP_CONF_MALFORMED_ERROR ), $this->getName() . ' ' . $version ),
00352                     $boxTitle
00353                 );
00354             }
00355 
00356             return false;
00357         }
00358 
00359         // bearsampp.conf
00360         $this->setVersion( $version );
00361 
00362         return true;
00363     }
