00398     public function setEnable($enabled, $showWindow = false)
00399     {
00400         global $bearsamppConfig, $bearsamppLang, $bearsamppWinbinder;
00401 
00402         if ( $enabled == Config::ENABLED && !is_dir( $this->currentPath ) ) {
00403             Log::debug( $this->getName() . ' cannot be enabled because bundle ' . $this->getVersion() . ' does not exist in ' . $this->currentPath );
00404             if ( $showWindow ) {
00405                 $bearsamppWinbinder->messageBoxError(
00406                     sprintf( $bearsamppLang->getValue( Lang::ENABLE_BUNDLE_NOT_EXIST ), $this->getName(), $this->getVersion(), $this->currentPath ),
00407                     sprintf( $bearsamppLang->getValue( Lang::ENABLE_TITLE ), $this->getName() )
00408                 );
00409             }
00410             $enabled = Config::DISABLED;
00411         }
00412 
00413         Log::info( $this->getName() . ' switched to ' . ($enabled == Config::ENABLED ? 'enabled' : 'disabled') );
00414         $this->enable = $enabled == Config::ENABLED;
00415         $bearsamppConfig->replace( self::ROOT_CFG_ENABLE, $enabled );
00416 
00417         $this->reload();
00418         if ( $this->enable ) {
00419             Util::installService( $this, $this->smtpPort, null, $showWindow );
00420         }
00421         else {
00422             Util::removeService( $this->service, $this->name );
00423         }
00424     }
